history.args:
$planPath = Join-Path (Get-Location) 'src\Space_Invaders\plan.md'
$planText = Get-Content -LiteralPath $planPath -Raw
$upgradeSection = [regex]::Match($planText, '(?s)## 4\. Exactly 20 modern enhancements(.*?)## 5\.').Groups[1].Value
$upgrades = [regex]::Matches($upgradeSection, '(?m)^\| (\d+) \|')
$importSection = [regex]::Match($planText, '(?s)### 9\.3 Exact internal import edges(.*?)### 9\.4').Groups[1].Value
$moduleRows = [System.Collections.Generic.List[object]]::new()
foreach ($planLine in ($importSection -split '\r?\n')) {
  if ($planLine -match '^\| `([^`]+\.js)` \| (.*)\|$') {
    $sourceFile = $Matches[1]
    $specifierText = $Matches[2]
    if (-not $sourceFile.StartsWith('src/')) { $sourceFile = 'src/' + $sourceFile }
    $moduleRows.Add([pscustomobject]@{ File = $sourceFile; Imports = $specifierText })
  }
}
$knownModules = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
foreach ($moduleRow in $moduleRows) { [void]$knownModules.Add([System.IO.Path]::GetFullPath((Join-Path (Get-Location) $moduleRow.File))) }
foreach ($cssFile in @('src/shared/ui/glass.css', 'src/Space_Invaders/game.css')) { [void]$knownModules.Add([System.IO.Path]::GetFullPath((Join-Path (Get-Location) $cssFile))) }
$importErrors = [System.Collections.Generic.List[string]]::new()
$internalEdges = 0
foreach ($moduleRow in $moduleRows) {
  $sourceDirectory = Split-Path ([System.IO.Path]::GetFullPath((Join-Path (Get-Location) $moduleRow.File))) -Parent
  foreach ($specifierMatch in [regex]::Matches($moduleRow.Imports, '`([^`]+)`')) {
    $specifier = $specifierMatch.Groups[1].Value
    if ($specifier.StartsWith('.')) {
      $internalEdges++
      $resolvedModule = [System.IO.Path]::GetFullPath((Join-Path $sourceDirectory $specifier))
      if (-not $knownModules.Contains($resolvedModule)) { $importErrors.Add($moduleRow.File + ' -> ' + $specifier) }
    }
  }
}
[pscustomobject]@{ UpgradeCount = $upgrades.Count; UpgradeNumbers = (($upgrades | ForEach-Object { $_.Groups[1].Value }) -join ', '); PlannedJavaScriptModules = $moduleRows.Count; InternalImportEdges = $internalEdges; UnresolvedPlannedImports = $importErrors.Count } | Format-List
$importErrors

